# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TOPLUMCU EĞİLİMLERİ YANSITAN ŞİİR ANLAYIŞI (1923-1960)</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">İçerik ve Düşünsel Özellikler</text>\n  <text x="42" y="96" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Sanat Anlayışı:</tspan> "Toplum için sanat" ilkesi;</text>\n  <text x="50" y="112" font-size="11.5" fill="#7f1d1d">şair toplumun sözcüsü ve öncüsüdür.</text>\n  <text x="42" y="136" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Ana Temalar:</tspan> Emek, işçi ve köylü sorunları,</text>\n  <text x="50" y="152" font-size="11.5" fill="#7f1d1d">yoksulluk, göç, sömürüye başkaldırı, eşitlik.</text>\n  <text x="42" y="176" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Üslup:</tspan> Hitabet (nutuk/söylev) tonu, coşkulu,</text>\n  <text x="50" y="192" font-size="11.5" fill="#7f1d1d">kitleleri harekete geçiren pragmatik (faydacı) dil.</text>\n  <rect x="42" y="202" width="280" height="28" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Marksist / Materyalist estetik ve gelecek umudu</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Biçim, Ahenk ve Fütürizm Etkisi</text>\n  <text x="378" y="96" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Serbest Nazım:</tspan> Düzenli ölçü (hece/aruz) ve</text>\n  <text x="386" y="112" font-size="11.5" fill="#1e3a8a">dörtlük bağları kırılmış; uzun-kısa dizeler.</text>\n  <text x="378" y="136" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Basamaklı Dize:</tspan> Kırık dizeler, büyük-küçük</text>\n  <text x="386" y="152" font-size="11.5" fill="#1e3a8a">harf oyunları ve görsel-işitsel ritim.</text>\n  <text x="378" y="176" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Edebî Akım:</tspan> <tspan font-weight="bold">Fütürizm</tspan> (Gelecekçilik — Marinetti</text>\n  <text x="386" y="192" font-size="11.5" fill="#1e3a8a">ve Rus şair <tspan font-weight="bold">Vladimir Mayakovski</tspan> etkisi).</text>\n  <rect x="378" y="202" width="280" height="28" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Makine, hız, çark ve fabrika seslerinin şiire girmesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SERBEST NAZMIN ÖNCÜSÜ: NÂZIM HİKMET RAN (1902-1963)</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Sanat Kişiliği ve Gelişim Çizgisi</text>\n  <text x="42" y="96" font-size="11.5" fill="#78350f">• İlk şiirlerini hece ölçüsüyle yazmış; Moskova</text>\n  <text x="50" y="112" font-size="11.5" fill="#78350f">yıllarında <tspan font-weight="bold">Mayakovski</tspan>\'den etkilenerek</text>\n  <text x="50" y="128" font-size="11.5" font-weight="bold" fill="#92400e">serbest nazmı ve fütürizmi başlatmıştır.</text>\n  <text x="42" y="152" font-size="11.5" fill="#78350f">• <tspan font-weight="bold">"Makinalaşmak"</tspan> (Trrrrum, trrrrum, trak tiki tak)</text>\n  <text x="50" y="168" font-size="11.5" fill="#78350f">şiiri fütürizmin edebiyatımızdaki tipik örneğidir.</text>\n  <text x="42" y="192" font-size="11.5" fill="#78350f">• Halk hikâyeleri, destan ve Divan edebiyatı</text>\n  <text x="50" y="208" font-size="11.5" fill="#78350f">unsurlarını modern toplumcu şiirle birleştirmiştir.</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Başlıca Eserleri (Şiir, Destan ve Oyun)</text>\n  <text x="378" y="96" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">İlk Serbest Şiirleri:</tspan> Güneşi İçenlerin Türküsü,</text>\n  <text x="386" y="112" font-size="11.5" fill="#14532d">835 Satır, Jokond ile Si-Ya-U, Varan 3, Sesini</text>\n  <text x="386" y="128" font-size="11.5" fill="#14532d">Kaybeden Şehir, Benerci Kendini Niçin Öldürdü</text>\n  <text x="378" y="152" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Destan / Epik Eserleri:</tspan> <tspan font-weight="bold">Kuvâyi Milliye Destanı</tspan>,</text>\n  <text x="386" y="168" font-size="11.5" fill="#14532d"><tspan font-weight="bold">Memleketimden İnsan Manzaraları</tspan>, Şeyh Bedrettin</text>\n  <text x="386" y="184" font-size="11.5" fill="#14532d">Destanı, Taranta-Babu\'ya Mektuplar</text>\n  <text x="378" y="208" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Tiyatroları:</tspan> Kafatası, Ferhad ile Şirin, Yusuf ile Menofis</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1923-1960 TOPLUMCU GERÇEKÇİ ŞAİRLER VE TEMSİLCİLERİ</text>\n  <rect x="20" y="48" width="210" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">RIFAT ILGAZ (1911-1993)</text>\n  <text x="35" y="96" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">1940 Kuşağı</tspan> toplumcu şairi</text>\n  <text x="42" y="112" font-size="11" fill="#1e3a8a">ve mizah/roman ustasıdır.</text>\n  <text x="35" y="134" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Markopaşa</tspan> dergisini çıkardı.</text>\n  <text x="35" y="156" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Şiirleri:</tspan> Yarenlik, Sınıf,</text>\n  <text x="42" y="172" font-size="11" fill="#1e3a8a">Yaşadıkça, Devam, Üsküdar\'da</text>\n  <text x="42" y="188" font-size="11" fill="#1e3a8a">Sabah Oldu, Karakılçık</text>\n  <text x="35" y="212" font-size="11" font-weight="bold" fill="#1d4ed8">• Roman: Hababam Sınıfı, Karartma Geceleri</text>\n  <rect x="245" y="48" width="210" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">CEYHUN ATUF KANSU</text>\n  <text x="260" y="96" font-size="11" fill="#581c87">• Çocuk doktoru; Anadolu\'nun</text>\n  <text x="267" y="112" font-size="11" fill="#581c87">yoksul çocuklarını, köylüsünü</text>\n  <text x="267" y="128" font-size="11" fill="#581c87">ve Millî Mücadele ruhunu işledi.</text>\n  <text x="260" y="152" font-size="11" fill="#581c87">• Halk şiiri geleneğini toplumcu</text>\n  <text x="267" y="168" font-size="11" fill="#581c87">gerçekçi duyarlılıkla birleştirdi.</text>\n  <text x="260" y="192" font-size="11" font-weight="bold" fill="#6b21a8">• Şiirleri: Bağbozumu Sofrası,</text>\n  <text x="267" y="208" font-size="11" font-weight="bold" fill="#6b21a8">Sakarya Meydan Savaşı, Yanık Hava,</text>\n  <text x="267" y="224" font-size="11" font-weight="bold" fill="#6b21a8">Çocuklar Gemisi, Bağımsızlık Gülü</text>\n  <rect x="470" y="48" width="210" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">DİĞER ÖNEMLİ ŞAİRLER</text>\n  <text x="485" y="96" font-size="11" fill="#78350f">• <tspan font-weight="bold">Ercüment Behzat Lav:</tspan></text>\n  <text x="492" y="112" font-size="10.5" fill="#78350f">Fütürizm, dadaizm, sürrealizm;</text>\n  <text x="492" y="128" font-size="10.5" font-weight="bold" fill="#92400e">S.O.S., Kaos, Açıl Kilidim Açıl, Mau Mau</text>\n  <text x="485" y="152" font-size="11" fill="#78350f">• <tspan font-weight="bold">Hasan İzzettin Dinamo:</tspan></text>\n  <text x="492" y="168" font-size="10.5" fill="#78350f">Deniz Gezintileri, Karacaahmet</text>\n  <text x="492" y="184" font-size="10.5" font-weight="bold" fill="#92400e">Senfonisi, Kutsal İsyan (Roman)</text>\n  <text x="485" y="208" font-size="11" fill="#78350f">• <tspan font-weight="bold">1940 Kuşağı:</tspan> A. Kadir, Enver Gökçe,</text>\n  <text x="492" y="224" font-size="10.5" fill="#78350f">Ahmet Arif (Hasretinden Prangalar Eskittim)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
